module protocol::ctoken_table;

use std::type_name::{Self, TypeName};
use sui::bag::{Self, Bag};
use sui::balance::{Self, Balance};

use sui::table::{Self, Table};

use protocol::ctoken::CToken;
use protocol::error;
use protocol::generic_store::{Self, GenericCoinTypeStorage};

/// Tracks the ctoken stored and the underlying coin types
public struct CTokenTable has key, store {
    id: UID,
    // a mapping from the underlying coin type to ctoken types
    coin_types: GenericCoinTypeStorage<TypeName>,
    // use table instead of vec set as one needs to query balance by TypeName while balances is a bag and borrow operations need explicit types
    ctoken_values: Table<TypeName, u64>,
    balances: Bag,
}

public(package) fun new(ctx: &mut TxContext): CTokenTable {
    CTokenTable {
        id: object::new(ctx),
        coin_types: generic_store::new(ctx),
        ctoken_values: table::new(ctx),
        balances: bag::new(ctx),
    }
}

public(package) fun ctoken_value_by_coin_type(self: &CTokenTable, name: TypeName): u64 {
    if (!self.coin_types.supports_type<TypeName>(name)) { 0 } 
    else {
        let ctoken_type = self.coin_types.load_by_type(name);
        self.ctoken_value_by_ctoken_type(*ctoken_type)
    }
}

public(package) fun ctoken_value_by_ctoken_type(self: &CTokenTable, name: TypeName): u64 {
    if (!self.ctoken_values.contains(name)) { return 0 };
    *self.ctoken_values.borrow(name)
}

public(package) fun is_supporting_collateral<MarketType, CoinType>(self: &CTokenTable): bool {
    let ctoken_type = ctoken_type_name<MarketType, CoinType>();
    self.ctoken_values.contains(ctoken_type)
}

public(package) fun supported_coin_types(self: &CTokenTable): vector<TypeName> {
    if (self.coin_types.is_empty()) { vector::empty() } 
    else { self.coin_types.keys() }
}

public(package) fun support_collateral_token<MarketType, CoinType>(self: &mut CTokenTable) {
    let ctoken_type = ctoken_type_name<MarketType, CoinType>();

    // we are using ctoken type as the checking key and only coin_types to track actual collateral
    assert!(!self.ctoken_values.contains(ctoken_type), error::constraint_double_support_ctoken());

    self.coin_types.store<TypeName, CoinType>(ctoken_type);

    self.balances.add(ctoken_type, balance::zero<CToken<MarketType, CoinType>>());
    self.ctoken_values.add(ctoken_type, 0);
}

public(package) fun join_ctoken<MarketType, CoinType>(self: &mut CTokenTable, balance: Balance<CToken<MarketType, CoinType>>) {
    assert!(balance.value() > 0, error::reserve_join_zero_value());
    assert!(self.coin_types.supports<TypeName, CoinType>());

    let ctoken_type = ctoken_type_name<MarketType, CoinType>();

    let in_bag_balance = bag::borrow_mut<TypeName, Balance<CToken<MarketType, CoinType>>>(&mut self.balances, ctoken_type);
    let total = in_bag_balance.join(balance);

    let val = self.ctoken_values.borrow_mut(ctoken_type);
    *val = total;
}

/// Reverts if amount is more than balance, caller should ensure the condition is met.
public(package) fun split_ctoken<MarketType, CoinType>(self: &mut CTokenTable, amount: u64): Balance<CToken<MarketType, CoinType>> {
    assert!(amount > 0, error::reserve_split_zero_value());

    let ctoken_type = ctoken_type_name<MarketType, CoinType>();
    let in_bag_balance = bag::borrow_mut<TypeName, Balance<CToken<MarketType, CoinType>>>(&mut self.balances, ctoken_type);

    assert!(in_bag_balance.value() >= amount, error::constraint_split_ctoken_too_many());

    let b = in_bag_balance.split(amount);
    if (in_bag_balance.value() == 0) {
        self.coin_types.remove<TypeName, CoinType>();

        let empty_balance = bag::remove<TypeName, Balance<CToken<MarketType, CoinType>>>(&mut self.balances, ctoken_type);
        empty_balance.destroy_zero();

        self.ctoken_values.remove(ctoken_type);
